mapper.select:
SELECT COUNT(*)
FROM AUTH_USER_MAPPING
WHERE EVENT_SEQ = #{eventSeq}
AND GENERAL_AUTH_CODE = #{authCode}

mapper.delete:
DELETE FROM AUTH_USER_MAPPING
WHERE EVENT_SEQ = #{eventSeq}
AND USER_KEY = #{userKey}

mapper.select:
SELECT COUNT(*)
FROM SURVEY_ANSWER a
INNER JOIN SURVEY_USER u ON a.EVENT_SEQ = u.EVENT_SEQ AND a.USER_SEQ = u.SEQ
WHERE u.EVENT_SEQ = #{eventSeq}
AND u.USER_KEY = #{userKey}

